import { Component, ComponentInterface, Element, Fragment, h, Host, Listen, Prop, State, Watch } from '@stencil/core';
import { NavigationSizes, Target } from '../../../../../../types';
import { AriaAttributes, extractAriaAttributes } from '../../../../../../utils/a11y-helper';
import { verifyTarget } from '../../../../../../utils/link-helper';

@Component({
  tag: 'groupui-global-side-navigation-utility-item',
  styleUrl: 'global-side-navigation-utility-item.scss',
  shadow: true,
})
export class GlobalSideNavigationUtilityItem implements ComponentInterface {
  /**
   * icon name e.g. 'clock-24'. Use the matching 24px sized icons
   */
  @Prop({ reflect: true }) readonly icon: string;

  /**
   * sets a custom icon source e.g. '...path/clock-24.svg', overrides icon property if both are set
   */
  @Prop({ reflect: true }) readonly iconSource: string;

  /**
   * set item as active
   */
  @Prop({ reflect: true, mutable: true }) active: boolean;

  /**
   * disables the navigation item
   */
  @Prop({ reflect: true }) readonly disabled: boolean;

  /**
   * URL that the hyperlink points to.
   */
  @Prop({ reflect: true }) readonly href: string;

  /**
   * where to open the linked URL. On target 'none' no target attribute will be set.
   */
  @Prop({ reflect: true }) readonly target: Target = 'self';

  /**
   * sets a custom accessible text for the icon
   */
  @Prop({ reflect: true, attribute: 'a11y-label-icon' }) readonly a11yLabelIcon: string;

  /**
   * @internal
   */
  @Prop({ reflect: true }) readonly size: NavigationSizes = 's';

  /**
   * @internal
   */
  @Prop({ reflect: true }) readonly divider: boolean;

  /**
   * @internal
   */
  @Prop({ reflect: true }) readonly iconOnly: boolean = false;

  @Element() host: HTMLElement;

  @State() private hasPopover: boolean;

  @State() private ariaAttributes: AriaAttributes;

  private linkRef: HTMLAnchorElement;

  componentWillLoad() {
    this.ariaAttributes = extractAriaAttributes(this.host);
  }

  disconnectedCallback(): void {
    this.detachWindowListeners();
  }

  @Listen('click')
  handleClick(event: Event): void {
    if (this.disabled) {
      event.preventDefault();
      event.stopImmediatePropagation();
      return;
    }
    if (!this.hasPopover) {
      return;
    }
    event.stopImmediatePropagation();
    if (this.isPopoverVisible()) {
      this.active = false;
      return;
    }
    this.active = true;
  }

  @Listen('focus')
  handleFocus(event: FocusEvent): void {
    if (this.disabled) {
      event.preventDefault();
      event.stopImmediatePropagation();
      this.host.blur();
    }
  }

  @Listen('keydown')
  handleKeyDown(event: KeyboardEvent): void {
    if (event.key === ' ') {
      this.linkRef?.click();
    }
  }

  @Watch('active')
  handlePopoverVisibilityChange(isVisible: boolean): void {
    if (!this.hasPopover) {
      return;
    }
    if (isVisible) {
      this.attachWindowListeners();
    } else {
      this.detachWindowListeners();
    }
  }

  private hasPopoverSlot(): boolean {
    const slot = this.host.shadowRoot.querySelector('slot[name="popover"]') as HTMLSlotElement;
    return slot && slot.assignedElements().length > 0;
  }

  private isPopoverVisible(): boolean {
    return this.hasPopover && this.active;
  }

  private attachWindowListeners(): void {
    window.addEventListener('click', this.handlePopoverClosingAction, true);
    window.addEventListener('keydown', this.handlePopoverClosingAction, true);
  }

  private detachWindowListeners(): void {
    window.removeEventListener('click', this.handlePopoverClosingAction, true);
    window.removeEventListener('keydown', this.handlePopoverClosingAction, true);
  }

  private handlePopoverClosingAction = (event: MouseEvent | KeyboardEvent) => {
    if (!this.isPopoverVisible()) {
      return;
    }
    const isEscapeKey = event instanceof KeyboardEvent && event.key === 'Escape';
    const isClickOutside = event instanceof MouseEvent && !event.composedPath().includes(this.host);

    if (isEscapeKey || isClickOutside) {
      this.active = false;
    }
  };

  private handleSlotChange = () => {
    this.hasPopover = this.hasPopoverSlot();
  };

  private clickableElement() {
    const commonProps = {
      tabIndex: this.disabled ? -1 : 0,
      slot: 'parent',
      class: this.isPopoverVisible() && 'popover-visible',
      ...this.ariaAttributes,
    };

    const itemContent = (
      <Fragment>
        {this.icon && (
          <groupui-icon
            aria-hidden={this.a11yLabelIcon ? null : 'true'}
            name={this.icon}
            src={this.iconSource}
            alt={this.a11yLabelIcon}
          />
        )}
        <slot name="avatar"></slot>
        {!this.iconOnly && <slot name="label"></slot>}
      </Fragment>
    );

    if (this.href) {
      return (
        <a
          {...commonProps}
          href={this.href}
          target={verifyTarget(this.target)}
          ref={(el) => (this.linkRef = el as HTMLAnchorElement)}
        >
          {itemContent}
        </a>
      );
    }

    return (
      <button {...commonProps} type="button" disabled={this.disabled}>
        {itemContent}
      </button>
    );
  }

  private iconOnlyWithoutIcon() {
    if (!this.iconOnly) return false;
    return !this.isAvatarSlotted() && !this.icon && !this.iconSource;
  }

  private isAvatarSlotted() {
    return (this.host.querySelector('[slot="avatar"]') as HTMLElement) !== null;
  }

  render() {
    if (this.iconOnlyWithoutIcon()) return;

    return (
      <Host>
        <div>
          <groupui-popover visible={this.isPopoverVisible()} placement="right-end" offset={0}>
            {this.clickableElement()}
            <slot slot="content" name="popover" onSlotchange={this.handleSlotChange}></slot>
          </groupui-popover>
        </div>
      </Host>
    );
  }
}
